-- ===========================================================================
-- MY DATABASE — complete schema, Pipeline Console
--
-- GENERATED by scripts/build-schema.mjs. Do not edit by hand: change the
-- migration under supabase/migrations and re-run `npm run schema:build`.
--
-- Every migration in order, with data statements removed. Run the whole file in
-- ONE Supabase SQL Editor tab. Safe against a live database: what remains is
-- tables, indexes, functions, triggers, policies and grants, all written
-- `if not exists` or `create or replace`.
--
-- WHAT WAS LEFT OUT, and why. These rewrite or delete rows rather than define
-- structure, so running them against a populated database would duplicate or
-- destroy real records:
--   0006_strip_source_prefix.sql — entire file: rewrites existing rfps.source values
--   0013_roles.sql — lines 115-119
--   0017_rfp_claims.sql — lines 60-70
--   0026_capability_statement_services.sql — lines 1-119
--   0027_remove_work_we_do_not_do.sql — entire file: deletes rfps rows that no longer qualify
--
-- Statements that only look like data are KEPT: inserts inside function bodies
-- (handle_new_user, seed_member_rfps, consume_api_quota, record_change,
-- empty_expired_proposal_archive) are part of those definitions, and the two
-- storage.buckets inserts create buckets rather than write user data.
-- ===========================================================================

-- ===========================================================================
-- 0001_init.sql
-- ===========================================================================

-- Pipeline Console — initial schema
--
-- Every row is owned by the authenticated user that created it and is only ever
-- visible to them. Date-only columns (`*_on`, `due`, `deadline`, `week_start`)
-- are written by the client from its *local* calendar date so that weekly
-- reporting lines up with the user's working week rather than UTC.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- leads -----
create table if not exists public.leads (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,
  org               text not null check (length(trim(org)) > 0),
  segment           text not null default 'Government',
  country           text not null default '',
  contact_name      text not null default '',
  contact_role      text not null default '',
  email             text not null default '',
  phone             text not null default '',
  status            text not null default 'New'
                      check (status in ('New', 'Contacted', 'Qualified',
                                        'Handed Over', 'Won', 'Lost')),
  next_action_date  date,
  source            text not null default '',
  notes             text not null default '',
  created_on        date not null default current_date,
  status_updated_on date,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists leads_user_created_idx
  on public.leads (user_id, created_at desc);
create index if not exists leads_user_status_idx
  on public.leads (user_id, status);

-- ----------------------------------------------------------------- rfps -----
create table if not exists public.rfps (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,
  title             text not null check (length(trim(title)) > 0),
  org               text not null default '',
  segment           text not null default 'Government',
  deadline          date,
  value             numeric(14, 2),
  status            text not null default 'Watching'
                      check (status in ('Watching', 'Preparing', 'Submitted',
                                        'Won', 'Lost')),
  link              text not null default '',
  notes             text not null default '',
  source            text not null default 'Manual',
  sourced           boolean not null default false,
  created_on        date not null default current_date,
  status_updated_on date,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists rfps_user_deadline_idx
  on public.rfps (user_id, deadline);

-- ---------------------------------------------------------------- tasks -----
create table if not exists public.tasks (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade,
  text         text not null check (length(trim(text)) > 0),
  due          date,
  priority     text not null default 'Normal' check (priority in ('Normal', 'High')),
  linked_lead  uuid references public.leads (id) on delete set null,
  done         boolean not null default false,
  completed_on date,
  created_on   date not null default current_date,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists tasks_user_due_idx
  on public.tasks (user_id, done, due);

-- ------------------------------------------------------- weekly_reports -----
create table if not exists public.weekly_reports (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  week_start date not null,
  revenue    numeric(14, 2),
  notes      text not null default '',
  submitted  boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One report per user per week; the client upserts on this constraint.
  unique (user_id, week_start)
);

create index if not exists weekly_reports_user_week_idx
  on public.weekly_reports (user_id, week_start desc);

-- ------------------------------------------------------------ updated_at ----
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['leads', 'rfps', 'tasks', 'weekly_reports'] loop
    execute format(
      'drop trigger if exists %I_touch_updated_at on public.%I', t, t);
    execute format(
      'create trigger %I_touch_updated_at before update on public.%I
         for each row execute function public.touch_updated_at()', t, t);
  end loop;
end;
$$;

-- ------------------------------------------------------------------ RLS -----
alter table public.leads           enable row level security;
alter table public.rfps            enable row level security;
alter table public.tasks           enable row level security;
alter table public.weekly_reports  enable row level security;

do $$
declare
  t text;
begin
  foreach t in array array['leads', 'rfps', 'tasks', 'weekly_reports'] loop
    execute format('drop policy if exists %I_select_own on public.%I', t, t);
    execute format('drop policy if exists %I_insert_own on public.%I', t, t);
    execute format('drop policy if exists %I_update_own on public.%I', t, t);
    execute format('drop policy if exists %I_delete_own on public.%I', t, t);

    execute format(
      'create policy %I_select_own on public.%I
         for select to authenticated using (auth.uid() = user_id)', t, t);
    execute format(
      'create policy %I_insert_own on public.%I
         for insert to authenticated with check (auth.uid() = user_id)', t, t);
    execute format(
      'create policy %I_update_own on public.%I
         for update to authenticated
         using (auth.uid() = user_id) with check (auth.uid() = user_id)', t, t);
    execute format(
      'create policy %I_delete_own on public.%I
         for delete to authenticated using (auth.uid() = user_id)', t, t);
  end loop;
end;
$$;


-- ===========================================================================
-- 0002_external_opportunities.sql
-- ===========================================================================

-- Track where a synced RFP came from, so re-running the CareerCraft sync
-- updates rather than duplicates.
--
-- Run this in the Supabase SQL Editor after 0001_init.sql.

alter table public.rfps
  add column if not exists external_id text;

-- Postgres treats NULLs as distinct in a unique index, so manually-added RFPs
-- (external_id null) never collide with each other — only synced rows are
-- constrained. Named so PostgREST can target it as an upsert conflict key.
create unique index if not exists rfps_user_external_id_key
  on public.rfps (user_id, external_id);

comment on column public.rfps.external_id is
  'Opportunity id from the CareerCraft public feed; null for manual entries.';


-- ===========================================================================
-- 0003_activities_and_qualification.sql
-- ===========================================================================

-- Activity log + lead qualification fields.
--
-- Closes the gaps between the console and the BDE job description:
--   * "Communication log" is the daily evidence for the Client communication
--     KPI, and outreach (calls, emails, LinkedIn, meeting requests) is a listed
--     responsibility. Tasks record what you intend to do; this records what you
--     actually did.
--   * Qualification requires assessing "need, timing, decision process, budget
--     potential and fit before handover", and databases segmented by priority.
--
-- Run in the Supabase SQL Editor after 0002. Safe to re-run.

-- ----------------------------------------------------------- activities -----
create table if not exists public.activities (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade,

  -- An entry may hang off a lead, an RFP, or neither (general market
  -- intelligence). Deleting the parent takes its log with it.
  lead_id      uuid references public.leads (id) on delete cascade,
  rfp_id       uuid references public.rfps (id) on delete cascade,

  type         text not null default 'Call'
                 check (type in ('Call', 'Email', 'LinkedIn', 'Meeting request',
                                 'Meeting held', 'Proposal sent', 'Demo',
                                 'Registration', 'Note')),
  occurred_on  date not null default current_date,
  summary      text not null check (length(trim(summary)) > 0),
  outcome      text not null default '',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists activities_user_date_idx
  on public.activities (user_id, occurred_on desc);
create index if not exists activities_lead_idx
  on public.activities (lead_id, occurred_on desc);
create index if not exists activities_rfp_idx
  on public.activities (rfp_id, occurred_on desc);

-- ------------------------------------------------ lead qualification --------
alter table public.leads
  add column if not exists priority text not null default 'Medium'
    check (priority in ('High', 'Medium', 'Low'));

alter table public.leads
  add column if not exists needs text not null default '';

alter table public.leads
  add column if not exists budget_band text not null default '';

alter table public.leads
  add column if not exists decision_timeline text not null default '';

alter table public.leads
  add column if not exists decision_process text not null default '';

comment on column public.leads.needs is
  'What the institution needs — the "need" half of qualification.';
comment on column public.leads.budget_band is
  'Indicative budget potential, free text (e.g. "KES 2-5M", "unfunded").';
comment on column public.leads.decision_timeline is
  'Timing / training calendar — when they buy, not when you called.';
comment on column public.leads.decision_process is
  'Who signs off and how, so handover notes are not guesswork.';

create index if not exists leads_user_priority_idx
  on public.leads (user_id, priority);

-- --------------------------------------------- monthly/quarterly reports ---
-- The job description has monthly deliverables and a quarterly strategy
-- review, not just the weekly portfolio report. `week_start` becomes the start
-- of whatever period the row covers, and `period` says which — without it a
-- month beginning on a Monday would collide with that week's report.
alter table public.weekly_reports
  add column if not exists period text not null default 'week'
    check (period in ('week', 'month', 'quarter'));

alter table public.weekly_reports
  drop constraint if exists weekly_reports_user_id_week_start_key;

create unique index if not exists weekly_reports_user_period_start_key
  on public.weekly_reports (user_id, period, week_start);

comment on column public.weekly_reports.week_start is
  'First day of the period this row covers; read together with `period`.';

