-- ===========================================================================
-- 0009_scheduled_sync.sql
-- ===========================================================================

-- Pull consultancy and training opportunities into the tracker every morning,
-- unattended.
--
-- Sources are World Bank, UNDP, UNGM, IUCN and AfDB, with ReliefWeb waiting on
-- an approved appname. They are configured in the Edge Function itself, not
-- here — this file only decides WHEN it runs, so adding a source later needs no
-- database change.
--
-- Without this the sync only runs while somebody has the console open. Nobody
-- opens it on a Saturday, so Monday's tracker would be missing the weekend's
-- notices until the first page load — and a deadline can pass in that gap.
--
-- Timing: 02:00 UTC is 05:00 in Nairobi (EAT, UTC+3, no DST). Postgres cron
-- schedules are UTC on Supabase, so the offset is baked into the expression.
--
-- BEFORE RUNNING: replace both placeholders below.
--   <PROJECT_REF>  your project ref (the subdomain of your Supabase URL)
--   <SERVICE_ROLE_KEY>  Project Settings -> API -> service_role
--
-- The service-role key sits in the job definition, readable by anyone with
-- database access. That is the same trust boundary as the key itself, but it is
-- the reason this job is worth deleting if you ever hand out DB credentials.
-- It is also what tells the function to sync EVERY user rather than one: the
-- in-app "Check now" button presents a user token instead and syncs only the
-- person who pressed it.
--
-- Deploy the function first, or the first run 404s:
--   supabase functions deploy sync-opportunities
--
-- Run in the Supabase SQL Editor after 0008. Safe to re-run.
--
-- To stop the morning run without touching the app:
--   select cron.unschedule('sync-opportunities-daily');

create extension if not exists pg_cron;
create extension if not exists pg_net;

-- Everything below is guarded on the placeholders having been replaced.
--
-- This file carries secrets it cannot supply itself, which makes it the one
-- migration that must not run unattended — and `supabase db push` replays every
-- migration in the folder without asking. Un-guarded, a push would unschedule a
-- working job and replace it with one posting to a literal "<PROJECT_REF>" URL,
-- silently killing the morning sync. So a push is now a no-op here, and the job
-- is only ever created by pasting this file into the SQL Editor with the values
-- filled in.
do $$
declare
  project_ref constant text := '<PROJECT_REF>';
  service_key constant text := '<SERVICE_ROLE_KEY>';
begin
  if project_ref like '<%>' or service_key like '<%>' then
    raise notice
      'sync-opportunities-daily not scheduled: placeholders still present. Paste this file into the SQL Editor with your project ref and service-role key to schedule it.';
    return;
  end if;

  -- Unschedule first so re-running this replaces the job rather than stacking a
  -- second copy that would double every morning's work.
  begin
    perform cron.unschedule('sync-opportunities-daily');
  exception
    when others then null; -- not scheduled yet
  end;

  perform cron.schedule(
    'sync-opportunities-daily',
    '0 2 * * *',
    format(
      $job$
      select net.http_post(
        url     := %L,
        headers := jsonb_build_object(
          'Content-Type',  'application/json',
          'Authorization', %L
        ),
        body    := '{}'::jsonb,
        -- Five sources are fetched concurrently, but UNGM pages through its
        -- results one request at a time and the insert runs once per user. The
        -- default 5s is nowhere near enough, and a timeout here would look like
        -- a silent no-op rather than a failure.
        timeout_milliseconds := 180000
      );
      $job$,
      'https://' || project_ref || '.supabase.co/functions/v1/sync-opportunities',
      'Bearer ' || service_key
    )
  );
end;
$$;

-- Check it registered:
--   select jobid, schedule, jobname, active from cron.job;
-- And what happened on the last runs:
--   select start_time, status, return_message
--     from cron.job_run_details
--    where jobid = (select jobid from cron.job where jobname = 'sync-opportunities-daily')
--    order by start_time desc limit 10;
--
-- The function returns a per-source breakdown in its response body, so a run
-- that succeeded overall while one scrape broke is visible there rather than
-- only in the function logs.


-- ===========================================================================
-- 0010_consultants.sql
-- ===========================================================================

-- The people a proposal is staffed with.
--
-- The drafter used to write team composition entirely in placeholders — the
-- doctrine tells it to list a role as one to confirm whenever the specialist
-- has not been supplied. This is where they get supplied from: at draft time
-- the roster is sent alongside the notice, and the model builds the team
-- section from real people with real qualifications instead.
--
-- Free text rather than lookup tables for expertise, sectors and countries.
-- These are read by a language model, not joined against — "Monitoring &
-- Evaluation, Youth Leadership" is exactly as useful to it as three foreign
-- keys would be, and a roster of this size does not need the ceremony. The
-- same reasoning already applies to rfps.service_areas.
--
-- Run in the Supabase SQL Editor after 0009. Safe to re-run.

create table if not exists public.consultants (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,

  name              text not null check (length(trim(name)) > 0),
  title             text not null default '',
  /** Comma-separated tags, e.g. "Monitoring & Evaluation, Grant Writing". */
  core_expertise    text not null default '',
  years_experience  integer,
  sectors           text not null default '',
  countries         text not null default '',

  qualifications    text not null default '',
  /**
   * The kinds of RFP component this person should be matched to. Carries more
   * weight than the bios when the drafter is choosing who to put forward,
   * because it is written in the language of the work rather than the person.
   */
  task_fit          text not null default '',
  project_experience text not null default '',
  languages         text not null default '',
  availability      text not null default '',

  /** ~50 words, ready to drop into a team-composition table. */
  short_bio         text not null default '',
  /** ~150 words, for a CV annex or a detailed technical proposal. */
  long_bio          text not null default '',

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists consultants_user_name_idx
  on public.consultants (user_id, name);

drop trigger if exists consultants_touch_updated_at on public.consultants;
create trigger consultants_touch_updated_at
  before update on public.consultants
  for each row execute function public.touch_updated_at();

alter table public.consultants enable row level security;

drop policy if exists consultants_select_own on public.consultants;
drop policy if exists consultants_insert_own on public.consultants;
drop policy if exists consultants_update_own on public.consultants;
drop policy if exists consultants_delete_own on public.consultants;

create policy consultants_select_own on public.consultants
  for select to authenticated using (auth.uid() = user_id);
create policy consultants_insert_own on public.consultants
  for insert to authenticated with check (auth.uid() = user_id);
create policy consultants_update_own on public.consultants
  for update to authenticated
  using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy consultants_delete_own on public.consultants
  for delete to authenticated using (auth.uid() = user_id);

comment on column public.consultants.task_fit is
  'RFP components this consultant should be matched to. Ranked on when the drafter picks a team.';


-- ===========================================================================
-- 0011_tender_document.sql
-- ===========================================================================

-- The tender document behind an opportunity, as text.
--
-- Until now the drafter worked from the notice alone — a title, a deadline and
-- whatever notes were typed in. Its own doctrine says so outright: "You have
-- the published notice only — not the full RFP document, evaluation matrix,
-- company profile, CVs or reference letters." That is the single biggest limit
-- on draft quality, because the scope, the evaluation criteria and the
-- mandatory requirements all live in the attached PDF.
--
-- Stored as text rather than as a file. The drafter can only read text, and the
-- extraction happens in the browser with pdf.js, so there is nothing to gain
-- from keeping the binary as well — `proposals` already exists for attachments
-- that are genuinely worth storing whole.
--
-- Run in the Supabase SQL Editor after 0010. Safe to re-run.

alter table public.rfps
  add column if not exists tender_text text not null default '';

alter table public.rfps
  add column if not exists tender_file_name text not null default '';

comment on column public.rfps.tender_text is
  'Text extracted from the tender PDF in the browser. Sent to the drafter so it works from the real scope rather than the notice alone.';
comment on column public.rfps.tender_file_name is
  'Original filename, so it is obvious which document the text came from.';


-- ===========================================================================
-- 0012_fit_score.sql
-- ===========================================================================

-- How well an opportunity fits what Vantage Africa actually delivers, 0-100.
--
-- The capability filter added in the sync already answers "can we bid this at
-- all?", so every row in the tracker is biddable. This answers the next
-- question — which of them first — because a week's worth arriving as an
-- undifferentiated list still leaves the triage to be done by hand.
--
-- Computed at sync time in the Edge Function rather than in a view, because it
-- reads the notice text the row was built from, which is not all kept. See
-- scoreFit in supabase/functions/sync-opportunities/normalize.ts.
--
-- Rows synced before this migration keep 0 and sort last under "Best fit".
-- Backfilling would mean re-scoring from titles alone, which is what the
-- ranking already does for new rows — so a re-sync is the honest fix if the
-- old rows matter.
--
-- Run in the Supabase SQL Editor after 0011. Safe to re-run.

alter table public.rfps
  add column if not exists fit_score integer not null default 0;

create index if not exists rfps_user_fit_score_idx
  on public.rfps (user_id, fit_score desc);

comment on column public.rfps.fit_score is
  'Capability fit, 0-100, summed from weighted capability matches at sync time. Ranking heuristic, not a probability of winning.';


-- ===========================================================================
-- 0013_roles.sql
-- ===========================================================================

-- Team access: three roles, private pipelines, oversight for the top two.
--
-- Until now every table answered one question — "is this row mine?" — and that
-- was the whole authorisation model. It works for one person and silently
-- fragments for eight: the same tender gets scraped into eight pipelines and
-- nobody can see what anyone else is bidding on.
--
-- The model here keeps each member's pipeline private, which is what was asked
-- for, and adds oversight above it:
--
--   super_user  own rows, reads everyone's, deletes anything, manages members
--   admin       own rows, reads everyone's, deletes anything
--   user        own rows only, and cannot delete
--
-- Two deliberate limits worth knowing:
--
-- Reading is not editing. An admin can see and delete another member's row but
-- cannot silently edit it, because a bid someone is mid-way through writing is
-- theirs until they hand it over. Widening that is one clause per table if the
-- oversight ever needs teeth.
--
-- The role lives in its own table rather than in auth.users metadata. App
-- metadata is writable from the client with a user's own token, so a role kept
-- there is a role any member can grant themselves.
--
-- Run in the Supabase SQL Editor. Safe to re-run.

-- `create type` has no IF NOT EXISTS, and this file is meant to be re-runnable.
do $$ begin
  create type public.member_role as enum ('super_user', 'admin', 'user');
exception when duplicate_object then null;
end $$;

create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text not null default '',
  full_name   text not null default '',
  role        public.member_role not null default 'user',
  /**
   * Cleared rather than deleted when someone leaves: their rows stay owned and
   * their history stays readable, but they cannot sign in and work.
   */
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

drop trigger if exists profiles_touch_updated_at on public.profiles;
create trigger profiles_touch_updated_at
  before update on public.profiles
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- helpers ---

-- SECURITY DEFINER so the function can read profiles from inside a policy on
-- profiles itself. Without it, "can this user read profiles?" would consult a
-- policy that has to read profiles to answer, and recurse.
--
-- search_path is pinned because a SECURITY DEFINER function that resolves its
-- own table names through the caller's search_path can be pointed at a
-- look-alike table by any member who can create a schema.
create or replace function public.current_role()
returns public.member_role
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select p.role from public.profiles p where p.id = auth.uid() and p.active),
    'user'::public.member_role
  );
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.current_role() in ('super_user', 'admin');
$$;

create or replace function public.is_super_user()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.current_role() = 'super_user';
$$;

-- A profile for every member, created with the account rather than by hand, so
-- there is no window in which a signed-in user has no row and no role.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, email)
  values (new.id, coalesce(new.email, ''))
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- --------------------------------------------------------------- profiles ---

alter table public.profiles enable row level security;

drop policy if exists profiles_select on public.profiles;
drop policy if exists profiles_update_self on public.profiles;
drop policy if exists profiles_manage on public.profiles;
drop policy if exists profiles_insert on public.profiles;

-- Everyone can see the team list. Knowing who your colleagues are is not
-- privileged information, and the app needs it to show who owns a record.
create policy profiles_select on public.profiles
  for select to authenticated using (true);

-- Anyone may edit their own name. Nobody may edit their own role or active
-- flag — that check lives in the trigger below, because a WITH CHECK clause
-- cannot see the row's previous values to compare against.
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

create policy profiles_manage on public.profiles
  for update to authenticated
  using (public.is_super_user()) with check (public.is_super_user());

create policy profiles_insert on public.profiles
  for insert to authenticated with check (public.is_super_user());

-- The privilege-escalation guard. Without it, `profiles_update_self` lets any
-- member set their own role to super_user — the policy only checks *which row*
-- is being written, not *which columns*.
create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if (new.role is distinct from old.role or new.active is distinct from old.active)
     and not public.is_super_user() then
    raise exception 'Only the super user can change a member''s role or access.';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_role on public.profiles;
create trigger profiles_guard_role
  before update on public.profiles
  for each row execute function public.guard_profile_role();

comment on table public.profiles is
  'Team members and their access level. Role is changed only by the super user; the guard trigger enforces it regardless of which policy allowed the write.';


-- ===========================================================================
-- 0014_role_policies.sql
-- ===========================================================================

-- Re-states every table's row-level security against the roles from 0013.
--
-- The shape is identical on all seven pipeline tables, so it is generated in a
-- loop rather than written out eight times. Reading eight near-identical copies
-- is how a policy ends up subtly different on one table and nobody notices
-- until someone sees a row they should not.
--
--   select   own rows, or anything at all for an admin or the super user
--   insert   own rows only — user_id is forced to the caller
--   update   own rows only, admins included; see the note in 0013 on why
--            oversight is read-and-delete rather than read-and-write
--   delete   admins and the super user only
--
-- The delete rule is the one that will surprise people: a standard user cannot
-- delete their own records either. That is deliberate — deletion is the single
-- action with no undo in this console, and it was scoped to the two roles that
-- answer for the data.
--
-- user_settings is left alone. It holds one row of the signed-in member's own
-- drafting guidance, nobody else has any reason to read it, and it has no
-- delete path to gate.
--
-- Run after 0013. Safe to re-run.

do $$
declare
  t text;
begin
  foreach t in array array[
    'leads', 'rfps', 'tasks', 'activities', 'weekly_reports', 'proposals', 'consultants'
  ]
  loop
    -- Old ownership-only policies, by the names 0001-0012 gave them.
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format('drop policy if exists %I on public.%I', t || '_insert_own', t);
    execute format('drop policy if exists %I on public.%I', t || '_update_own', t);
    execute format('drop policy if exists %I on public.%I', t || '_delete_own', t);

    -- and this migration's own, so it can be re-run.
    execute format('drop policy if exists %I on public.%I', t || '_select', t);
    execute format('drop policy if exists %I on public.%I', t || '_insert', t);
    execute format('drop policy if exists %I on public.%I', t || '_update', t);
    execute format('drop policy if exists %I on public.%I', t || '_delete', t);

    execute format($p$
      create policy %I on public.%I for select to authenticated
      using (user_id = auth.uid() or public.is_admin())
    $p$, t || '_select', t);

    execute format($p$
      create policy %I on public.%I for insert to authenticated
      with check (user_id = auth.uid())
    $p$, t || '_insert', t);

    execute format($p$
      create policy %I on public.%I for update to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid())
    $p$, t || '_update', t);

    execute format($p$
      create policy %I on public.%I for delete to authenticated
      using (public.is_admin())
    $p$, t || '_delete', t);
  end loop;
end $$;


-- ===========================================================================
-- 0015_role_guard_service.sql
-- ===========================================================================

-- Lets the members service actually set a role.
--
-- 0013 added a trigger that refuses any change to `role` or `active` unless
-- `is_super_user()` says so, and `is_super_user()` reads `auth.uid()`. The
-- manage-members function connects with the service-role key, where there is
-- no `auth.uid()` at all — so the trigger read the one caller that is allowed
-- to do this as the one caller that is not, and refused it.
--
-- The symptom was narrow enough to miss: creating a member as `user` worked,
-- because the role never actually changed from its default. Only creating an
-- admin failed.
--
-- The fix keys on the database role rather than the JWT. PostgREST switches to
-- `service_role` for a service-key request, and there is no way to reach that
-- role from a browser — the key that grants it is the one thing never shipped
-- to a client. `postgres` and `supabase_admin` are included so the first super
-- user can be set from the SQL editor without disabling the trigger, which was
-- otherwise the documented bootstrap and is a bad habit to require.
--
-- Run after 0013. Safe to re-run.

create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.role is not distinct from old.role
     and new.active is not distinct from old.active then
    return new;
  end if;

  -- A trusted server-side connection: the members function, or a maintainer in
  -- the SQL editor. Never a signed-in member, whose requests arrive as
  -- `authenticated`.
  if current_user in ('service_role', 'postgres', 'supabase_admin') then
    return new;
  end if;

  if public.is_super_user() then
    return new;
  end if;

  raise exception 'Only the super user can change a member''s role or access.';
end;
$$;


-- ===========================================================================
-- 0016_role_guard_fix.sql
-- ===========================================================================

-- Closes a privilege-escalation hole opened by 0015.
--
-- 0015 let a trusted server-side connection through the role guard by testing
-- `current_user in ('service_role', 'postgres', 'supabase_admin')`. Inside a
-- SECURITY DEFINER function — which this trigger is, and has to be —
-- `current_user` is the function's *owner*, not the caller. The owner is
-- `postgres`. So the check was true for every caller, and the guard let any
-- signed-in member set their own role to super_user.
--
-- Caught by testing the escalation rather than reading the code: a plain PATCH
-- of /rest/v1/profiles from a standard user's token came back with an empty
-- body, which reads like a refusal, and the role had changed anyway.
--
-- The caller is identified by the JWT role claim instead, which SECURITY
-- DEFINER does not rewrite:
--
--   'authenticated'  a signed-in member  -> must be the super user
--   'service_role'   the members function -> allowed
--   null             a direct database connection (SQL editor, migration,
--                    psql) -> allowed, and this is the bootstrap path for the
--                    first super user
--
-- A member cannot forge the claim: it is signed into the token by the auth
-- server, and the key that mints a service_role token is never shipped to a
-- browser.
--
-- Run after 0015. Safe to re-run.

create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  claims text;
  jwt_role text;
begin
  if new.role is not distinct from old.role
     and new.active is not distinct from old.active then
    return new;
  end if;

  -- `true` makes a missing setting return null rather than raising; an unset
  -- GUC can also come back as the empty string, which is not valid json.
  claims := nullif(current_setting('request.jwt.claims', true), '');
  jwt_role := case when claims is null then null else claims::json ->> 'role' end;

  -- No JWT: a direct database connection, not a request from the app.
  if jwt_role is null then
    return new;
  end if;

  if jwt_role = 'service_role' then
    return new;
  end if;

  if public.is_super_user() then
    return new;
  end if;

  raise exception 'Only the super user can change a member''s role or access.';
end;
$$;


-- ===========================================================================
-- 0017_rfp_claims.sql
-- ===========================================================================

-- One tender, one bidder.
--
-- Every member has their own copy of each scraped opportunity — that is what
-- the per-user sync produces, and it is why two people could take the same
-- tender into their pipeline without either knowing. Two bids from the same
-- firm on one tender is worse than no bid: it splits the effort, confuses the
-- buyer, and usually disqualifies both.
--
-- The claim is kept in its own table rather than as a flag on the rows,
-- because the rows are per-member and a flag on one copy says nothing about
-- the other seven. Here there is exactly one row per tender across the whole
-- firm, and the primary key does the enforcing: a second claim is not a race
-- to be resolved but a duplicate key, refused by the database.
--
-- Keyed on `external_id` — the source's own id for the notice ("worldbank:
-- OP00456106") — which is the only identifier every member's copy shares.
-- Hand-added RFPs have no external id and need no claim: nobody else can see
-- them to take them.
--
-- Run in the Supabase SQL Editor. Safe to re-run.

create table if not exists public.rfp_claims (
  /** The source's id for the notice. One row per tender, firm-wide. */
  external_id text primary key,
  claimed_by  uuid not null references auth.users (id) on delete cascade,
  claimed_at  timestamptz not null default now(),
  /**
   * Copied rather than joined. A member sees every claim, including ones on
   * tenders their own sync has not pulled yet, and a join to a row they cannot
   * read would show them a blank line instead of a title.
   */
  title       text not null default ''
);

create index if not exists rfp_claims_claimed_by_idx
  on public.rfp_claims (claimed_by);

alter table public.rfp_claims enable row level security;

drop policy if exists rfp_claims_select on public.rfp_claims;
drop policy if exists rfp_claims_insert on public.rfp_claims;
drop policy if exists rfp_claims_delete on public.rfp_claims;

-- Everyone sees every claim. That is the entire point: a tender you cannot
-- take should say who has it, not simply refuse.
create policy rfp_claims_select on public.rfp_claims
  for select to authenticated using (true);

-- You may only claim in your own name. Taking a tender "for" someone else is
-- not a thing this supports.
create policy rfp_claims_insert on public.rfp_claims
  for insert to authenticated with check (claimed_by = auth.uid());

-- Release your own; an admin can release anyone's, which is what happens when
-- someone leaves mid-bid or drops one they had taken.
create policy rfp_claims_delete on public.rfp_claims
  for delete to authenticated
  using (claimed_by = auth.uid() or public.is_admin());

comment on table public.rfp_claims is
  'One row per scraped tender, firm-wide. The primary key is what stops two members bidding the same opportunity.';


-- ===========================================================================
-- 0018_seed_member_rfps.sql
-- ===========================================================================

-- Gives a new member the tender pool on their first sign-in.
--
-- Scraped opportunities are stored per member, so an account created today
-- owns nothing and opens the tracker to an empty page. The 05:00 run would
-- fill it, but only with what the sources publish tomorrow — and only after a
-- day of the console looking broken to someone who has just been given it.
--
-- This copies the currently open tenders from what the firm already holds.
-- Deliberately a *clean* copy: status back to Watching, notes and any attached
-- tender document dropped, nothing marked as in a pipeline. What a colleague
-- has written about a bid is theirs, and a new member inheriting someone
-- else's working notes would be both confusing and a small privacy leak.
--
-- Closed tenders are skipped. They cannot be bid on, and the tracker hides
-- them by default anyway.
--
-- SECURITY DEFINER because it writes rows owned by somebody else, which no
-- policy permits and should not. It is called by the members function straight
-- after an account is created; `revoke ... from public` keeps it off the API
-- surface so a member cannot call it for themselves.
--
-- Run after 0017. Safe to re-run — the unique index on (user_id, external_id)
-- makes a second call a no-op.

create or replace function public.seed_member_rfps(target uuid)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  copied integer;
begin
  if target is null then
    return 0;
  end if;

  insert into public.rfps (
    user_id, title, org, segment, deadline, value, status, link, notes,
    source, sourced, created_on, external_id, in_pipeline, opportunity_type,
    kenya, service_areas, fit_score
  )
  -- One row per tender: the pool is duplicated across existing members, so
  -- without DISTINCT ON the new member would get several copies of each.
  select distinct on (r.external_id)
    target, r.title, r.org, r.segment, r.deadline, r.value, 'Watching',
    r.link, '', r.source, r.sourced, r.created_on, r.external_id, false,
    r.opportunity_type, r.kenya, r.service_areas, r.fit_score
  from public.rfps r
  where r.external_id is not null
    and (r.deadline is null or r.deadline >= current_date)
  order by r.external_id, r.created_at desc
  on conflict (user_id, external_id) do nothing;

  get diagnostics copied = row_count;
  return copied;
end;
$$;

revoke all on function public.seed_member_rfps(uuid) from public;
revoke all on function public.seed_member_rfps(uuid) from anon, authenticated;


-- ===========================================================================
-- 0019_rls_performance.sql
-- ===========================================================================

-- Stops the access check running once per row.
--
-- 0014 wrote every table's read policy as
--
--   using (user_id = auth.uid() or public.is_admin())
--
-- Both of those are function calls sitting in a row filter, so Postgres calls
-- them for every row it examines. `is_admin()` queries `profiles` each time, so
-- reading 478 RFPs asked "what is this person's role?" 478 times — and then did
-- it again for leads, tasks, activities, proposals, reports and consultants on
-- the same page load. It got slower the moment members were added, because
-- adding members is what makes the tables grow.
--
-- Wrapping a call in `(select ...)` turns it into an InitPlan: evaluated once
-- for the whole statement and reused. The result is identical — both functions
-- are STABLE and cannot change mid-statement — so this is purely a matter of
-- how many times the planner chooses to ask.
--
-- Putting the admin check first also lets the common case short-circuit: for a
-- standard user it resolves to false immediately and what remains is
-- `user_id = <constant>`, which the existing (user_id, ...) indexes can serve
-- instead of scanning the table.
--
-- Run after 0014. Safe to re-run.

do $$
declare
  t text;
begin
  foreach t in array array[
    'leads', 'rfps', 'tasks', 'activities', 'weekly_reports', 'proposals', 'consultants'
  ]
  loop
    execute format('drop policy if exists %I on public.%I', t || '_select', t);
    execute format('drop policy if exists %I on public.%I', t || '_insert', t);
    execute format('drop policy if exists %I on public.%I', t || '_update', t);
    execute format('drop policy if exists %I on public.%I', t || '_delete', t);

    execute format($p$
      create policy %I on public.%I for select to authenticated
      using ((select public.is_admin()) or user_id = (select auth.uid()))
    $p$, t || '_select', t);

    execute format($p$
      create policy %I on public.%I for insert to authenticated
      with check (user_id = (select auth.uid()))
    $p$, t || '_insert', t);

    execute format($p$
      create policy %I on public.%I for update to authenticated
      using (user_id = (select auth.uid()))
      with check (user_id = (select auth.uid()))
    $p$, t || '_update', t);

    execute format($p$
      create policy %I on public.%I for delete to authenticated
      using ((select public.is_admin()))
    $p$, t || '_delete', t);
  end loop;
end $$;

-- The same treatment for the two tables 0013/0017 added.
drop policy if exists rfp_claims_insert on public.rfp_claims;
create policy rfp_claims_insert on public.rfp_claims
  for insert to authenticated with check (claimed_by = (select auth.uid()));

drop policy if exists rfp_claims_delete on public.rfp_claims;
create policy rfp_claims_delete on public.rfp_claims
  for delete to authenticated
  using (claimed_by = (select auth.uid()) or (select public.is_admin()));

drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

drop policy if exists profiles_manage on public.profiles;
create policy profiles_manage on public.profiles
  for update to authenticated
  using ((select public.is_super_user())) with check ((select public.is_super_user()));

drop policy if exists profiles_insert on public.profiles;
create policy profiles_insert on public.profiles
  for insert to authenticated with check ((select public.is_super_user()));


-- ===========================================================================
-- 0020_team_overview.sql
-- ===========================================================================

-- Firm-wide figures that count tenders rather than copies of tenders.
--
-- Every member holds their own copy of each scraped opportunity, so anything
-- that adds up per-member numbers counts the same tender once per member. With
-- five accounts the console would report 1,195 "active RFPs" when there were
-- 263 — a number that grows when you hire, which is not what anyone reading it
-- would take it to mean.
--
-- Counting is therefore done here, over `distinct external_id`, rather than by
-- summing what each dashboard shows. Hand-added RFPs have no external id and
-- are genuinely one-per-member, so they fall back to their own row id and count
-- individually — which is correct: two members each entering a tender by hand
-- really are two records.
--
-- SECURITY DEFINER so it can see across members, with an explicit role check
-- inside — the function reads everyone's rows, so it must refuse anyone who is
-- not entitled to that rather than relying on the caller to only ask nicely.
--
-- Run after 0019. Safe to re-run.

create or replace function public.team_overview()
returns json
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  result json;
begin
  if not public.is_admin() then
    raise exception 'Only an admin or the super user can read firm-wide figures.';
  end if;

  select json_build_object(
    -- One entry per real tender, however many members hold a copy.
    'open_tenders', (
      select count(distinct coalesce(r.external_id, r.id::text))
      from public.rfps r
      where r.deadline is null or r.deadline >= current_date
    ),
    'all_tenders', (
      select count(distinct coalesce(r.external_id, r.id::text))
      from public.rfps r
    ),
    -- In-pipeline rows are already one per tender across the firm: a claim is
    -- exclusive, and a hand-added RFP is only ever in its author's list. So
    -- this is a plain count, not a distinct one.
    'in_pipeline', (
      select count(*) from public.rfps r where r.in_pipeline
    ),
    'unclaimed_open', (
      select count(distinct r.external_id)
      from public.rfps r
      where r.external_id is not null
        and (r.deadline is null or r.deadline >= current_date)
        and not exists (
          select 1 from public.rfp_claims c where c.external_id = r.external_id
        )
    )
  ) into result;

  return result;
end;
$$;

revoke all on function public.team_overview() from public;
grant execute on function public.team_overview() to authenticated;

comment on function public.team_overview() is
  'Firm-wide tender counts, deduplicated across members. Admin and super user only.';


-- ===========================================================================
-- 0021_single_admin.sql
-- ===========================================================================

-- Exactly one admin, enforced by the database.
--
-- The console is meant to have one super user, one admin and everyone else as
-- users. "One admin" kept as a rule people follow is a rule that lasts until
-- somebody is in a hurry; kept as a unique index it cannot be broken at all,
-- including by a direct SQL edit that bypasses the app entirely.
--
-- A unique index on `role` filtered to admins means the second admin row is a
-- duplicate key rather than a policy question. The super user is unaffected —
-- the filter only covers 'admin' — and there is no limit on plain users.
--
-- Any existing extra admins must be demoted before this can be created; the
-- index will refuse to build otherwise, which is the correct failure. It says
-- the data does not match the rule instead of quietly picking a winner.
--
-- Run in the Supabase SQL Editor. Safe to re-run.

create unique index if not exists profiles_one_admin
  on public.profiles (role)
  where role = 'admin';

comment on index public.profiles_one_admin is
  'At most one admin. A second is a duplicate key, not a judgement call.';


-- ===========================================================================
-- 0022_delete_super_user_only.sql
-- ===========================================================================

-- Deletion belongs to the super user alone.
--
-- 0014 gave it to both admin roles. The admin now has everything else the
-- super user has — reading every member's pipeline, running the sync, the
-- firm-wide figures — and deletion is the single exception alongside managing
-- members.
--
-- The reason it is the exception: it is the only action in this console with
-- no undo. Removing an RFP cascades to its activities and proposals, so one
-- click can take a bid someone else is mid-way through writing, and there is
-- nothing to restore it from. Everything else an admin can do is either
-- reversible or read-only.
--
-- Standard users still have no delete at all, which is unchanged.
--
-- Run after 0019. Safe to re-run.

do $$
declare
  t text;
begin
  foreach t in array array[
    'leads', 'rfps', 'tasks', 'activities', 'weekly_reports', 'proposals', 'consultants'
  ]
  loop
    execute format('drop policy if exists %I on public.%I', t || '_delete', t);
    execute format($p$
      create policy %I on public.%I for delete to authenticated
      using ((select public.is_super_user()))
    $p$, t || '_delete', t);
  end loop;
end $$;

-- Releasing a tender claim is not deletion in the destructive sense — it hands
-- the opportunity back so somebody else can take it, and nothing is lost. The
-- admin keeps that, which is what lets them free a tender held by someone who
-- has left or moved on.
drop policy if exists rfp_claims_delete on public.rfp_claims;
create policy rfp_claims_delete on public.rfp_claims
  for delete to authenticated
  using (claimed_by = (select auth.uid()) or (select public.is_admin()));


-- ===========================================================================
-- 0023_locked_tenders_read_only.sql
-- ===========================================================================

-- A tender someone else holds is read-only, enforced rather than hidden.
--
-- The profile page already withholds the draft, edit, attach and log controls
-- when another member has claimed the tender. That is the visible half. This is
-- the half that survives someone opening the console and calling the API
-- directly, which is the only half that counts as protection.
--
-- Every member holds their own copy of a scraped tender, so nothing stopped one
-- of them editing *their* copy of a notice another member is bidding: their own
-- row, their own user_id, permitted by the previous policy. The result would
-- have been two people quietly working the same tender in parallel — worse than
-- the duplicate bidding the claim was introduced to prevent, because it leaves
-- no trace.
--
-- Applies to admins and the super user too. Oversight is reading; an admin who
-- needs to act releases the claim first, which is a deliberate act that shows
-- up rather than a silent edit.
--
-- Hand-added RFPs have no external id, match no claim, and are unaffected.
--
-- Run after 0022. Safe to re-run.

-- The predicate, written once. Both policies below ask the same question:
-- "is this tender held by somebody other than me?"
create or replace function public.tender_held_by_other(target_external_id text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.rfp_claims c
     where c.external_id = target_external_id
       and c.claimed_by <> auth.uid()
  );
$$;

drop policy if exists rfps_update on public.rfps;
create policy rfps_update on public.rfps
  for update to authenticated
  using (
    user_id = (select auth.uid())
    and not (select public.tender_held_by_other(external_id))
  )
  with check (
    user_id = (select auth.uid())
    and not (select public.tender_held_by_other(external_id))
  );

-- Drafting is an insert into proposals, so blocking the button is not enough:
-- the draft would still save. The parent RFP is the caller's own copy, and its
-- external id is what ties it to the claim.
drop policy if exists proposals_insert on public.proposals;
create policy proposals_insert on public.proposals
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and not exists (
      select 1 from public.rfps r
       where r.id = proposals.rfp_id
         and public.tender_held_by_other(r.external_id)
    )
  );

-- Same reasoning for logging activity against a tender someone else is bidding.
drop policy if exists activities_insert on public.activities;
create policy activities_insert on public.activities
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and (
      rfp_id is null
      or not exists (
        select 1 from public.rfps r
         where r.id = activities.rfp_id
           and public.tender_held_by_other(r.external_id)
      )
    )
  );

comment on function public.tender_held_by_other(text) is
  'True when a claim on this tender belongs to somebody other than the caller. The read-only rule for locked tenders.';


-- ===========================================================================
-- 0024_consultant_files.sql
-- ===========================================================================

-- A photo and a CV for each consultant.
--
-- The roster already carries what a proposal's team-composition table needs in
-- structured form. What it could not carry is the two things a bid actually has
-- to attach: the CV itself, which almost every tender demands as an annex, and
-- a photo for the profiles a buyer sees.
--
-- Files go to storage rather than into the row. A CV is a megabyte of PDF that
-- nothing queries and everything would carry — the roster is loaded on every
-- draft, and pulling five CVs into memory to render a list of names would cost
-- more than the whole rest of the snapshot.
--
-- Paths are `{owner uid}/{consultant id}/{kind}.{ext}`. The leading uid is not
-- decoration: the storage policies compare that first segment to auth.uid(),
-- so the shape is what makes a file private rather than a convention.
--
-- Run in the Supabase SQL Editor. Safe to re-run.

alter table public.consultants
  add column if not exists photo_path   text not null default '',
  add column if not exists cv_path      text not null default '',
  add column if not exists cv_file_name text not null default '',
  add column if not exists cv_size      bigint;

comment on column public.consultants.cv_path is
  'Storage object path in the consultants bucket. The CV a tender asks for as an annex.';

-- ---------------------------------------------------------------- storage ---

insert into storage.buckets (id, name, public)
values ('consultants', 'consultants', false)
on conflict (id) do nothing;

drop policy if exists consultant_files_select_own on storage.objects;
drop policy if exists consultant_files_insert_own on storage.objects;
drop policy if exists consultant_files_update_own on storage.objects;
drop policy if exists consultant_files_delete_own on storage.objects;

-- The roster is per-account, so the files are too. An admin reading across the
-- firm sees other members' consultant *rows* but not their files; a CV is a
-- named individual's personal document, and widening that is a decision about
-- someone who is not in this system to make it.
create policy consultant_files_select_own on storage.objects
  for select to authenticated
  using (
    bucket_id = 'consultants'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy consultant_files_insert_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'consultants'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- Replacing a photo overwrites in place, which is an update rather than an
-- insert; without this, changing a photo fails while adding one works.
create policy consultant_files_update_own on storage.objects
  for update to authenticated
  using (
    bucket_id = 'consultants'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy consultant_files_delete_own on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'consultants'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );


-- ===========================================================================
-- 0025_call_report.sql
-- ===========================================================================

-- The call report a visiting officer files after seeing a client.
--
-- Split across two tables, because the form's fields answer two different
-- questions and they change at different rates.
--
-- A client is visited more than once. Everything about the visit therefore
-- belongs to the visit — which this console already models, as an activity
-- tied to a lead. Putting the report on the lead instead would give each
-- client one report, silently overwritten by the next visit, and the second
-- report would quietly destroy the first.
--
-- What stays on the lead is what does not change between visits: where the
-- client is, and what business they are in. Six fields the form asks for are
-- not added anywhere, because the record already answers them: "Name of
-- client" is leads.org, "Phone of Contact Person" is leads.phone beside
-- leads.contact_name, and "Date of visit" is activities.occurred_on. A second
-- copy of any of them is how a report and a record start disagreeing about a
-- client's phone number.
--
-- Run after 0024. Safe to re-run.

-- ---------------------------------------------------------------- the client
alter table public.leads
  add column if not exists location text not null default '',
  add column if not exists nature_of_business text not null default '';

comment on column public.leads.location is
  'Physical location of the client — the call report wants the address, not the country.';
comment on column public.leads.nature_of_business is
  'What the client actually does, as distinct from `segment`, which is the category we file them under.';

-- ----------------------------------------------------------------- the visit
-- Nullable-by-default throughout: most activities are a phone call or an email
-- and will never carry a report, and a report that cannot be part-filled is a
-- report nobody starts.
alter table public.activities
  add column if not exists visiting_officers text not null default '',
  add column if not exists officials_met text not null default '',
  add column if not exists report_date date,
  add column if not exists meeting_purpose text not null default '',
  -- The four numbered sections of the form.
  add column if not exists business_background text not null default '',
  add column if not exists key_needs text not null default '',
  add column if not exists way_forward text not null default '',
  add column if not exists other_comments text not null default '';

comment on column public.activities.visiting_officers is
  'Vantage Africa staff who made the visit. Free text: a visit is often two people, and one of them is not always a console account.';
comment on column public.activities.officials_met is
  'Names and titles of the client officials met, one per line.';
comment on column public.activities.report_date is
  'When the report was written, as distinct from occurred_on — the gap between them is the thing management reads the pair for.';
comment on column public.activities.key_needs is
  'Section 2 of the form. Falls back to the lead''s `needs` when blank, so a first visit does not have to restate what qualification already established.';

-- Finding the visits that have a report on them, for the lead page and the
-- activity register. Partial, because the overwhelming majority of activities
-- are calls and emails that will never carry one.
create index if not exists activities_with_report
  on public.activities (lead_id, occurred_on desc)
  where report_date is not null;


-- ===========================================================================
-- 0026_capability_statement_services.sql
-- ===========================================================================

comment on column public.rfps.service_areas is
  'Services this notice touches, comma-separated. The vocabulary is section 4 of the Corporate Capability Statement — see CAPABILITIES in sync-opportunities/normalize.ts, which is the only writer.';


-- ===========================================================================
-- 0028_oversight_can_act.sql
-- ===========================================================================

-- Let oversight act on a tender somebody else has taken, and hand it to
-- somebody else.
--
-- 0023 made a held tender read-only and said so explicitly for admins too:
-- "Oversight is reading; an admin who needs to act releases the claim first."
-- That was the wrong call in practice. Releasing a claim to fix a typo hands
-- the tender back to the pool where anyone can take it, which is a far larger
-- act than the edit being made — and it left the super user, who owns the
-- workspace, unable to touch a bid a member had left half-finished or to move
-- one to a colleague when somebody went on leave. The lock exists to stop two
-- members bidding the same tender in parallel, not to stop the person
-- responsible for the pipeline from managing it.
--
-- Standard users are unchanged: a tender held by a colleague stays read-only,
-- which is the case the lock was built for.
--
-- Run after 0027.

-- ------------------------------------------------------------------ editing
-- `with check` has to admit the admin too, or an admin updating a member's row
-- passes the `using` clause and is then rejected for leaving user_id pointing
-- at somebody else — which is precisely what editing another member's tender
-- means.
drop policy if exists rfps_update on public.rfps;
create policy rfps_update on public.rfps
  for update to authenticated
  using (
    (select public.is_admin())
    or (
      user_id = (select auth.uid())
      and not (select public.tender_held_by_other(external_id))
    )
  )
  with check (
    (select public.is_admin())
    or (
      user_id = (select auth.uid())
      and not (select public.tender_held_by_other(external_id))
    )
  );

-- Drafting and logging against a held tender, same reasoning. The row still has
-- to belong to the writer — an admin drafts on their own copy or on the row
-- they have reassigned to themselves — but the claim no longer blocks them.
drop policy if exists proposals_insert on public.proposals;
create policy proposals_insert on public.proposals
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and (
      (select public.is_admin())
      or not exists (
        select 1 from public.rfps r
         where r.id = proposals.rfp_id
           and public.tender_held_by_other(r.external_id)
      )
    )
  );

drop policy if exists activities_insert on public.activities;
create policy activities_insert on public.activities
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and (
      rfp_id is null
      or (select public.is_admin())
      or not exists (
        select 1 from public.rfps r
         where r.id = activities.rfp_id
           and public.tender_held_by_other(r.external_id)
      )
    )
  );

-- Oversight may move a claim as part of a reassignment. Members still release
-- only their own.
drop policy if exists rfp_claims_update on public.rfp_claims;
create policy rfp_claims_update on public.rfp_claims
  for update to authenticated
  using (claimed_by = (select auth.uid()) or (select public.is_admin()))
  with check (true);

-- -------------------------------------------------------------- reassigning
/**
 * Hands a tender, and everything attached to it, to another member.
 *
 * A function rather than a sequence of updates from the browser because it is
 * four writes across four tables that have to agree afterwards. Half of it
 * applied — the tender moved but the claim did not — leaves the firm-wide lock
 * pointing at somebody who no longer holds the bid, which is the exact failure
 * the claim exists to prevent.
 *
 * SECURITY DEFINER so it can write rows the caller does not own, with the
 * privilege check written out below rather than left to row-level security.
 */
create or replace function public.reassign_rfp(target uuid, new_owner uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_owner uuid;
  tender_external_id text;
  is_in_pipeline boolean;
begin
  if not public.is_admin() then
    raise exception 'Only an admin or the super user can reassign a tender.'
      using errcode = '42501';
  end if;

  select user_id, external_id, in_pipeline
    into current_owner, tender_external_id, is_in_pipeline
    from public.rfps where id = target;

  if not found then
    raise exception 'That tender no longer exists.' using errcode = 'P0002';
  end if;

  -- Checked against profiles rather than auth.users: a member switched off has
  -- an account but no business being handed a live bid.
  if not exists (
    select 1 from public.profiles p where p.id = new_owner and p.active
  ) then
    raise exception 'That member does not exist or has no access.'
      using errcode = 'P0002';
  end if;

  if current_owner = new_owner then
    return;
  end if;

  -- Every member holds their own copy of a scraped tender, so the new owner
  -- probably already has one. Two rows for one opportunity in their tracker is
  -- the confusing outcome, so their untouched copy goes — untouched meaning
  -- exactly what 0027 meant by it, and anything else is left alone rather than
  -- risking a cascade through work somebody did.
  if tender_external_id is not null then
    delete from public.rfps dup
     where dup.user_id = new_owner
       and dup.external_id = tender_external_id
       and dup.id <> target
       and dup.in_pipeline = false
       and not exists (select 1 from public.activities a where a.rfp_id = dup.id)
       and not exists (select 1 from public.proposals p where p.rfp_id = dup.id);
  end if;

  update public.rfps set user_id = new_owner where id = target;

  -- The work follows the tender. A proposal the new owner cannot read is a
  -- proposal that may as well have been deleted: the select policy is scoped by
  -- user_id, so leaving these behind would hide them from the person now
  -- responsible for the bid.
  update public.proposals set user_id = new_owner where rfp_id = target;
  update public.activities set user_id = new_owner where rfp_id = target;

  -- And the firm-wide lock, so nobody else can take what was just handed over.
  if tender_external_id is not null and is_in_pipeline then
    insert into public.rfp_claims (external_id, claimed_by, title)
    values (
      tender_external_id,
      new_owner,
      coalesce((select title from public.rfps where id = target), '')
    )
    on conflict (external_id) do update set claimed_by = excluded.claimed_by;
  end if;
end;
$$;

comment on function public.reassign_rfp(uuid, uuid) is
  'Moves a tender, its proposals, its activities and its claim to another member. Admin and super user only.';

revoke all on function public.reassign_rfp(uuid, uuid) from public;
grant execute on function public.reassign_rfp(uuid, uuid) to authenticated;


-- ===========================================================================
-- 0029_oversight_can_draft.sql
-- ===========================================================================

-- Let oversight draft on a tender a member has taken, into that member's name.
--
-- 0028 let an admin insert a proposal against a held tender, but kept the
-- original `user_id = auth.uid()` rule, so the draft landed owned by the admin.
-- The select policy on proposals is `is_admin() or user_id = auth.uid()`, which
-- means the member whose bid it was could not read the draft written for them.
-- A proposal only oversight can see is not help; it is a second copy of the bid
-- in a place the person doing the work never looks.
--
-- So the rule changes from "a proposal belongs to whoever wrote it" to "a
-- proposal belongs to the owner of its tender". That is not a new constraint
-- being imposed on old data: all 16 proposals held today already satisfy it,
-- because until now the only writer was the tender's owner. It is the same
-- invariant, finally written down — and once written down, an admin can be
-- allowed to write a row in somebody else's name without ambiguity about whose
-- bid it belongs to.
--
-- Standard users are unchanged: they may still only write against their own
-- tender, and still not against one a colleague has claimed.
--
-- Files are a separate matter and are handled below.
--
-- Run after 0028.

-- ------------------------------------------------------------------ the row
drop policy if exists proposals_insert on public.proposals;
create policy proposals_insert on public.proposals
  for insert to authenticated
  with check (
    -- Whoever writes it, the proposal belongs to the tender's owner.
    user_id = (
      select r.user_id from public.rfps r where r.id = proposals.rfp_id
    )
    and (
      (select public.is_admin())
      or (
        user_id = (select auth.uid())
        and not exists (
          select 1 from public.rfps r
           where r.id = proposals.rfp_id
             and public.tender_held_by_other(r.external_id)
        )
      )
    )
  );

-- Editing one — starring it as an exemplar, renaming it — follows the same
-- reasoning as 0028's rfps_update: oversight can act, members cannot reach
-- across.
drop policy if exists proposals_update on public.proposals;
create policy proposals_update on public.proposals
  for update to authenticated
  using ((select public.is_admin()) or user_id = (select auth.uid()))
  with check ((select public.is_admin()) or user_id = (select auth.uid()));

-- ---------------------------------------------------------------- the files
-- Object paths begin with a uid and the policies compare that first segment to
-- the caller's. That is what makes a submitted document private to its owner,
-- and it is also what stops an admin attaching one on a member's behalf: the
-- path has to name the member for them to read it afterwards, and naming the
-- member is exactly what the insert policy refuses.
--
-- Admins are therefore matched on the folder belonging to any member rather
-- than on it being their own. Standard users are unchanged — the first segment
-- must still be their own uid, so a member still cannot read, write or delete
-- a colleague's file.
drop policy if exists proposal_files_select_own on storage.objects;
create policy proposal_files_select_own on storage.objects
  for select to authenticated
  using (
    bucket_id = 'proposals'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      or (select public.is_admin())
    )
  );

drop policy if exists proposal_files_insert_own on storage.objects;
create policy proposal_files_insert_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'proposals'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      -- An admin may write into a member's folder, but the folder still has to
      -- be a member's: without this, any path at all would pass.
      or (
        (select public.is_admin())
        and exists (
          select 1 from public.profiles p
           where p.id::text = (storage.foldername(name))[1]
        )
      )
    )
  );

drop policy if exists proposal_files_delete_own on storage.objects;
create policy proposal_files_delete_own on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'proposals'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      or (select public.is_admin())
    )
  );

comment on column public.proposals.user_id is
  'The owner of the parent tender, not necessarily whoever wrote the row — oversight may draft on a member''s bid. Enforced by proposals_insert; see migration 0029.';

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0030_tender_understanding.sql
-- ===========================================================================

-- Somewhere to keep what the tender is actually about.
--
-- The drafter was writing twenty-three-section proposals from a 99-character
-- title. Measured on the live tracker: 1,218 tenders, not one with a tender
-- document attached, notes averaging eight characters. No amount of prompt
-- doctrine fixes that — the model was being asked to respond to a scope it had
-- never been shown, so it invented a plausible one.
--
-- Two columns, because they answer different questions and are refreshed at
-- different times.
--
-- `notice_text` is the source material: the published notice, fetched from its
-- own link and stripped to readable text. Distinct from `tender_text`, which is
-- the full ToR someone uploaded by hand — that one is authoritative and this
-- one is merely what the portal said, so a draft that has both should prefer
-- the upload and neither should overwrite the other.
--
-- `analysis` is the drafter's structured reading of the assignment: client,
-- objectives, scope, deliverables, evaluation criteria, mandatory requirements,
-- assignment type, ambiguities. It is kept rather than recomputed so it can be
-- read and corrected before a proposal is written against it, which is the
-- point — an understanding nobody can inspect is a guess with better manners.
--
-- Run after 0029.

alter table public.rfps
  add column if not exists notice_text text not null default '',
  add column if not exists analysis text not null default '',
  add column if not exists analysed_at timestamptz;

comment on column public.rfps.notice_text is
  'The published notice as fetched from `link` and reduced to readable text. Source material, not authoritative — an uploaded ToR in `tender_text` outranks it.';
comment on column public.rfps.analysis is
  'The drafter''s structured reading of the assignment, written before any proposal and kept so it can be checked and corrected. See migration 0030.';
comment on column public.rfps.analysed_at is
  'When the analysis was produced. A tender edited since then may have moved on from it.';

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0031_tender_intelligence.sql
-- ===========================================================================

-- Layout-aware tender ingestion, structured analysis, enrichment and RAG.
create extension if not exists vector with schema extensions;

alter table public.rfps
  add column if not exists ingestion jsonb not null default '{}'::jsonb,
  add column if not exists analysis_json jsonb not null default '{}'::jsonb,
  add column if not exists enrichment jsonb not null default '{}'::jsonb,
  add column if not exists intelligence_updated_at timestamptz;

create table if not exists public.knowledge_chunks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  source_type text not null check (source_type in ('proposal','case_study','consultant_cv','methodology','company_fact')),
  source_id text not null default '',
  title text not null,
  content text not null,
  metadata jsonb not null default '{}'::jsonb,
  embedding extensions.vector(1536) not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists knowledge_chunks_owner_idx on public.knowledge_chunks(user_id, source_type);
create index if not exists knowledge_chunks_embedding_idx on public.knowledge_chunks
  using hnsw (embedding extensions.vector_cosine_ops);

alter table public.knowledge_chunks enable row level security;
drop policy if exists knowledge_chunks_select_own on public.knowledge_chunks;
drop policy if exists knowledge_chunks_insert_own on public.knowledge_chunks;
drop policy if exists knowledge_chunks_update_own on public.knowledge_chunks;
drop policy if exists knowledge_chunks_delete_own on public.knowledge_chunks;
create policy knowledge_chunks_select_own on public.knowledge_chunks for select to authenticated using (auth.uid() = user_id);
create policy knowledge_chunks_insert_own on public.knowledge_chunks for insert to authenticated with check (auth.uid() = user_id);
create policy knowledge_chunks_update_own on public.knowledge_chunks for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy knowledge_chunks_delete_own on public.knowledge_chunks for delete to authenticated using (auth.uid() = user_id);

create or replace function public.match_knowledge_chunks(
  query_embedding extensions.vector(1536),
  match_count integer default 12,
  minimum_similarity double precision default 0.35
)
returns table (id uuid, source_type text, source_id text, title text, content text, metadata jsonb, similarity double precision)
language sql stable security invoker set search_path = public, extensions
as $$
  select k.id, k.source_type, k.source_id, k.title, k.content, k.metadata,
         1 - (k.embedding <=> query_embedding) as similarity
  from public.knowledge_chunks k
  where k.user_id = auth.uid()
    and 1 - (k.embedding <=> query_embedding) >= minimum_similarity
  order by k.embedding <=> query_embedding
  limit greatest(1, least(match_count, 50));
$$;

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0032_security_hardening.sql
-- ===========================================================================

-- Security boundaries that must hold even when a caller bypasses the UI.

create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.active = true
  );
$$;

revoke all on function public.is_active_user() from public;
grant execute on function public.is_active_user() to authenticated;

-- Restrictive policies are ANDed with every existing ownership/admin policy.
-- This closes the old gap where active=false changed the UI role but an old
-- session could still use the REST API against rows owned by the same uid.
do $$
declare
  t text;
begin
  foreach t in array array[
    'leads', 'rfps', 'tasks', 'weekly_reports', 'activities', 'user_settings',
    'proposals', 'profiles', 'rfp_claims', 'consultants', 'knowledge_chunks'
  ] loop
    execute format('drop policy if exists active_members_only on public.%I', t);
    execute format(
      'create policy active_members_only on public.%I as restrictive for all to authenticated
       using ((select public.is_active_user()))
       with check ((select public.is_active_user()))',
      t
    );
  end loop;
end;
$$;

drop policy if exists active_members_only on storage.objects;
create policy active_members_only on storage.objects
  as restrictive for all to authenticated
  using (
    bucket_id not in ('proposals', 'consultants')
    or (select public.is_active_user())
  )
  with check (
    bucket_id not in ('proposals', 'consultants')
    or (select public.is_active_user())
  );

-- A normal member may keep or release their own claim, but cannot transfer it
-- to an arbitrary colleague by issuing a direct UPDATE.
drop policy if exists rfp_claims_update on public.rfp_claims;
create policy rfp_claims_update on public.rfp_claims
  for update to authenticated
  using (claimed_by = (select auth.uid()) or (select public.is_admin()))
  with check (claimed_by = (select auth.uid()) or (select public.is_admin()));

-- Storage enforces these limits even when uploads bypass the browser checks.
update storage.buckets
set file_size_limit = 26214400,
    allowed_mime_types = array[
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'application/vnd.ms-powerpoint',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/zip'
    ]
where id = 'proposals';

update storage.buckets
set file_size_limit = 15728640,
    allowed_mime_types = array[
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'image/jpeg', 'image/png', 'image/webp', 'image/gif'
    ]
where id = 'consultants';

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0033_api_usage_limits.sql
-- ===========================================================================

-- Atomic per-user limits for paid AI operations.

create table if not exists public.api_usage (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  action text not null,
  created_at timestamptz not null default now()
);

create index if not exists api_usage_user_action_time_idx
  on public.api_usage (user_id, action, created_at desc);

alter table public.api_usage enable row level security;
-- No direct policies: callers can consume a quota through the function but
-- cannot inspect, insert or erase the accounting rows themselves.

create or replace function public.consume_api_quota(
  quota_action text,
  max_calls integer,
  window_seconds integer
)
returns boolean
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  caller uuid := auth.uid();
  used integer;
begin
  if caller is null or not public.is_active_user() then
    return false;
  end if;
  if quota_action is null or length(quota_action) > 64
     or max_calls < 1 or max_calls > 1000
     or window_seconds < 60 or window_seconds > 86400 then
    raise exception 'Invalid quota parameters.' using errcode = '22023';
  end if;

  -- Serialize the count-and-insert for this user/action so simultaneous calls
  -- cannot all observe the same remaining slot.
  perform pg_advisory_xact_lock(hashtext(caller::text), hashtext(quota_action));

  select count(*) into used
  from public.api_usage u
  where u.user_id = caller
    and u.action = quota_action
    and u.created_at >= now() - make_interval(secs => window_seconds);

  if used >= max_calls then return false; end if;
  insert into public.api_usage (user_id, action) values (caller, quota_action);
  return true;
end;
$$;

revoke all on function public.consume_api_quota(text, integer, integer) from public;
grant execute on function public.consume_api_quota(text, integer, integer) to authenticated;

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0034_rfp_realtime.sql
-- ===========================================================================

-- Keep open dashboards aligned when an admin refreshes the firm-wide pool.
do $$
begin
  if not exists (
    select 1
    from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'rfps'
  ) then
    alter publication supabase_realtime add table public.rfps;
  end if;
end;
$$;


-- ===========================================================================
-- 0035_profile_name_charset.sql
-- ===========================================================================

-- What a display name may contain, enforced by the database.
--
-- The console already refuses markup in a name: the sign-in field whitelists
-- what a username is made of, and manage-members validates the pair before it
-- creates an account. Neither covers this table.
--
-- `profiles` is writable directly by its owner — that is the point of the
-- self-service rename in migration 0013 — so a member's own row can be PATCHed
-- straight through PostgREST with whatever the caller likes, without passing
-- through any function this project controls. A check in TypeScript is a
-- message for the person filling in the form; this is the rule.
--
-- Names are otherwise left alone. Apostrophes, accents, hyphens and periods are
-- all ordinary in real names and all permitted; what is refused is the markup
-- and control characters that make a name into something other than a name.
--
-- NOT VALID deliberately: it binds every insert and update from here on without
-- re-checking rows already stored, so applying this can never fail on a name
-- somebody entered before the rule existed. Run VALIDATE CONSTRAINT later if
-- the existing rows are worth confirming.

alter table public.profiles
  drop constraint if exists profiles_full_name_charset;

alter table public.profiles
  add constraint profiles_full_name_charset
  check (full_name !~ '[<>{}\\|`]' and full_name !~ '[\x00-\x1F\x7F]')
  not valid;

comment on constraint profiles_full_name_charset on public.profiles is
  'A display name carries no markup or control characters. Mirrors identityProblem() in supabase/functions/manage-members.';


-- ===========================================================================
-- 0036_impersonation_audit.sql
-- ===========================================================================

-- Records every super-user switch into a standard member account.
create table if not exists public.impersonation_audit (
  id bigint generated always as identity primary key,
  actor_id uuid not null references auth.users(id) on delete restrict,
  target_id uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  check (actor_id <> target_id)
);

create index if not exists impersonation_audit_created_idx
  on public.impersonation_audit (created_at desc);

alter table public.impersonation_audit enable row level security;

-- The Edge Function writes with service role. Super users may inspect the log,
-- but nobody can edit or delete it through the Data API.
drop policy if exists impersonation_audit_select on public.impersonation_audit;
create policy impersonation_audit_select on public.impersonation_audit
  for select to authenticated
  using ((select public.is_super_user()));

notify pgrst, 'reload schema';


-- ===========================================================================
-- 0037_document_history_archive_audit.sql
-- ===========================================================================

alter table public.proposals
  add column if not exists version_no integer not null default 1,
  add column if not exists archived_at timestamptz,
  add column if not exists archived_by uuid references auth.users(id);
create index if not exists proposals_archive_expiry_idx on public.proposals (archived_at) where archived_at is not null;

with numbered as (
  select id, row_number() over (partition by rfp_id order by created_at, id) as n from public.proposals
) update public.proposals p set version_no = n.n from numbered n where n.id = p.id;

create or replace function public.assign_proposal_version() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform pg_advisory_xact_lock(hashtextextended(new.rfp_id::text, 0));
  select coalesce(max(version_no), 0) + 1 into new.version_no from public.proposals where rfp_id = new.rfp_id;
  return new;
end $$;
drop trigger if exists proposals_assign_version on public.proposals;
create trigger proposals_assign_version before insert on public.proposals for each row execute function public.assign_proposal_version();

create table if not exists public.audit_log (
  id bigint generated always as identity primary key, actor_id uuid references auth.users(id), owner_id uuid,
  table_name text not null, record_id text not null,
  action text not null check (action in ('created','updated','archived','restored','deleted')),
  changed_fields text[] not null default '{}', old_data jsonb, new_data jsonb,
  created_at timestamptz not null default now()
);
create index if not exists audit_log_created_idx on public.audit_log (created_at desc);
alter table public.audit_log enable row level security;
drop policy if exists audit_log_select on public.audit_log;
create policy audit_log_select on public.audit_log for select using (
  public.is_admin() or actor_id = (select auth.uid()) or owner_id = (select auth.uid())
);

create or replace function public.record_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare old_j jsonb; new_j jsonb; act text; owner uuid; fields text[];
begin
  old_j := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  new_j := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  owner := coalesce((new_j->>'user_id')::uuid, (old_j->>'user_id')::uuid);
  if tg_op = 'INSERT' then act := 'created'; fields := array(select jsonb_object_keys(new_j));
  elsif tg_op = 'DELETE' then act := 'deleted'; fields := '{}';
  else
    fields := array(select key from jsonb_each(new_j) where value is distinct from old_j->key);
    if old_j->>'archived_at' is null and new_j->>'archived_at' is not null then act := 'archived';
    elsif old_j->>'archived_at' is not null and new_j->>'archived_at' is null then act := 'restored';
    else act := 'updated'; end if;
  end if;
  insert into public.audit_log(actor_id, owner_id, table_name, record_id, action, changed_fields, old_data, new_data)
  values ((select auth.uid()), owner, tg_table_name, coalesce(new_j->>'id', old_j->>'id'), act, fields, old_j, new_j);
  return coalesce(new, old);
end $$;

do $$ declare t text; begin
  foreach t in array array['leads','rfps','tasks','activities','weekly_reports','proposals','consultants'] loop
    execute format('drop trigger if exists audit_%I on public.%I', t, t);
    execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function public.record_change()', t, t);
  end loop;
end $$;

create or replace function public.empty_expired_proposal_archive() returns integer
language plpgsql security definer set search_path = public as $$
declare removed integer; begin
  delete from public.proposals where archived_at < now() - interval '30 days';
  get diagnostics removed = row_count; return removed;
end $$;
revoke all on function public.empty_expired_proposal_archive() from public, anon, authenticated;

-- pg_cron is enabled by migration 0009. Replacing the named job keeps this
-- migration idempotent in local and preview environments.
do $$ begin
  if exists (select 1 from cron.job where jobname = 'purge-proposal-recycle-bin') then
    perform cron.unschedule('purge-proposal-recycle-bin');
  end if;
  perform cron.schedule('purge-proposal-recycle-bin', '15 2 * * *',
    'select public.empty_expired_proposal_archive()');
end $$;
comment on column public.proposals.archived_at is 'Recycle-bin timestamp; eligible for permanent deletion after 30 days.';


-- ===========================================================================
-- 0038_restrict_records_to_oversight.sql
-- ===========================================================================

-- Records and audit history are an oversight function. Members continue to
-- work with their own live records, but cannot browse the audit ledger.
drop policy if exists audit_log_select on public.audit_log;
create policy audit_log_select on public.audit_log
  for select
  using (public.is_admin());

comment on policy audit_log_select on public.audit_log is
  'Only admin and super_user roles can read the audit trail.';


-- ===========================================================================
-- 0039_teams_and_rfp_shares.sql
-- ===========================================================================

-- Sharing a tender with a colleague, and standing teams to share with.
--
-- Until now the only way to see somebody else's tender was to be oversight.
-- That is the right default — 0013 kept pipelines private on purpose — but it
-- leaves no room for the ordinary case of two people working one bid, and the
-- workaround people reach for instead is worse: hand the claim over, or paste
-- the notice into a second pipeline where it becomes a duplicate nobody
-- reconciles.
--
-- WHAT A SHARE IS, AND IS NOT
-- A share grants READ on one tender, to one member or one team. It never
-- grants write. That is a deliberate limit and the same one 0013 drew for
-- oversight: "a bid someone is mid-way through writing is theirs until they
-- hand it over." Co-editing is a bigger decision than co-reading and would
-- need to answer what happens when two people save the same field; this
-- feature does not pretend to have answered it. Every update, insert and
-- delete policy in the database is untouched by this migration.
--
-- WHY THE SHARE POINTS AT `rfps.id` AND NOT AT A CLAIM
-- `rfp_claims` is the firm-wide identity of a tender and was the obvious
-- candidate. It is the wrong one here for two reasons. Hand-added tenders have
-- no external id and therefore no claim, and they are exactly the rows most
-- worth sharing, being the ones a colleague cannot simply find in their own
-- copy of the feed. And a claim says who is bidding, not which rows to open:
-- resolving one back to a readable row means finding the claimant's copy,
-- which is the join this table stores directly.
--
-- WHY TEAMS AND PER-MEMBER SHARES BOTH EXIST
-- They answer different questions. A team is standing structure — the three
-- people who work health tenders — and survives the tender it was created for.
-- A per-member share is ad hoc: one colleague, one bid, this week. Forcing the
-- ad-hoc case through a team leaves behind a litter of two-person teams named
-- after tenders that closed months ago.
--
-- Run after 0038. Safe to re-run.

-- ------------------------------------------------------------------ teams ---

create table if not exists public.teams (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(trim(name)) > 0),
  created_by  uuid not null references auth.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Case-insensitively unique. Two teams called "Health" and "health" is a
-- support ticket, not a distinction anyone meant to draw.
create unique index if not exists teams_name_key
  on public.teams (lower(trim(name)));

drop trigger if exists teams_touch_updated_at on public.teams;
create trigger teams_touch_updated_at
  before update on public.teams
  for each row execute function public.touch_updated_at();

create table if not exists public.team_members (
  team_id   uuid not null references public.teams (id) on delete cascade,
  user_id   uuid not null references auth.users (id) on delete cascade,
  added_by  uuid not null references auth.users (id) on delete cascade,
  added_at  timestamptz not null default now(),
  primary key (team_id, user_id)
);

-- The lookup every read does: which teams am I in?
create index if not exists team_members_user_idx
  on public.team_members (user_id);

-- ----------------------------------------------------------------- shares ---

create table if not exists public.rfp_shares (
  id         uuid primary key default gen_random_uuid(),
  rfp_id     uuid not null references public.rfps (id) on delete cascade,
  /** Exactly one of these is set — see the check constraint. */
  user_id    uuid references auth.users (id) on delete cascade,
  team_id    uuid references public.teams (id) on delete cascade,
  shared_by  uuid not null references auth.users (id) on delete cascade,
  shared_at  timestamptz not null default now(),
  constraint rfp_shares_one_subject check (num_nonnulls(user_id, team_id) = 1)
);

-- Partial rather than a plain unique on (rfp_id, user_id, team_id): NULLs do
-- not compare equal in a unique index, so a composite one would happily admit
-- the same member twice.
create unique index if not exists rfp_shares_member_key
  on public.rfp_shares (rfp_id, user_id) where user_id is not null;
create unique index if not exists rfp_shares_team_key
  on public.rfp_shares (rfp_id, team_id) where team_id is not null;

create index if not exists rfp_shares_rfp_idx on public.rfp_shares (rfp_id);
create index if not exists rfp_shares_user_idx on public.rfp_shares (user_id);
create index if not exists rfp_shares_team_idx on public.rfp_shares (team_id);

-- ---------------------------------------------------------------- helpers ---

-- Every tender shared with me, directly or through a team I am in.
--
-- RETURNS AN ARRAY, AND THAT IS THE WHOLE POINT. The obvious shape for this is
-- `can_read_rfp(rfp_id) returns boolean`, which reads better and is the wrong
-- thing entirely: a function taking the row's own id cannot be hoisted out of
-- the row filter, so it runs once per row examined. That is precisely the
-- mistake 0019 was written to undo — it found `is_admin()` being called 478
-- times to read 478 RFPs. Returning the whole set instead lets the policy
-- unnest it in an uncorrelated subquery, which the planner runs once and
-- hashes. See the note on `rfps_select` for the form that does and does not
-- parse — the obvious spelling of this is a type error, not a slow query.
--
-- SECURITY DEFINER because the policy on `rfps` calls this, and this reads
-- `rfp_shares`, whose own policy reads `rfps` to find out who owns the row. As
-- a plain function that is a loop the planner refuses to run. As a definer
-- function it steps outside RLS and the loop never forms. It leaks nothing: it
-- returns only rows already keyed to the caller's own id.
create or replace function public.shared_rfp_ids()
returns uuid[]
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(array_agg(distinct s.rfp_id), array[]::uuid[])
  from public.rfp_shares s
  where s.user_id = auth.uid()
     or s.team_id in (
       select tm.team_id from public.team_members tm where tm.user_id = auth.uid()
     );
$$;

-- Does the caller own this tender? Used by the share policies to answer "may
-- you give this away?" without reading `rfps` through its own policy.
create or replace function public.owns_rfp(target uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.rfps r where r.id = target and r.user_id = auth.uid()
  );
$$;

-- ------------------------------------------------------------- team policy ---

alter table public.teams enable row level security;
alter table public.team_members enable row level security;

drop policy if exists teams_select on public.teams;
drop policy if exists teams_write on public.teams;
drop policy if exists team_members_select on public.team_members;
drop policy if exists team_members_write on public.team_members;

-- Readable by everyone, for the same reason `profiles` is: you cannot pick a
-- team to share with from a list you are not allowed to see, and which teams
-- the firm has is not privileged information.
create policy teams_select on public.teams
  for select to authenticated using (true);

-- Managed by the super user alone, matching who may already add members and
-- set their access. A team is a standing grant of read across pipelines, which
-- is an access decision, and 0013 put those in exactly one pair of hands.
create policy teams_write on public.teams
  for all to authenticated
  using ((select public.is_super_user()))
  with check ((select public.is_super_user()));

create policy team_members_select on public.team_members
  for select to authenticated using (true);

create policy team_members_write on public.team_members
  for all to authenticated
  using ((select public.is_super_user()))
  with check ((select public.is_super_user()));

-- ------------------------------------------------------------ share policy ---

alter table public.rfp_shares enable row level security;

drop policy if exists rfp_shares_select on public.rfp_shares;
drop policy if exists rfp_shares_insert on public.rfp_shares;
drop policy if exists rfp_shares_delete on public.rfp_shares;

-- You can see a share if you granted it, if you own the tender it is on, if it
-- is pointed at you, or if you are oversight. Notably a team share is visible
-- to the whole team: "who else has this?" is a fair question for anyone who
-- can already read the tender.
create policy rfp_shares_select on public.rfp_shares
  for select to authenticated
  using (
    (select public.is_admin())
    or shared_by = (select auth.uid())
    or user_id = (select auth.uid())
    or public.owns_rfp(rfp_id)
    or team_id in (
      select tm.team_id from public.team_members tm where tm.user_id = (select auth.uid())
    )
  );

-- Granting. The tender's owner or oversight, and nobody else — a member who
-- was shared a tender cannot pass it on further, which keeps the list of who
-- can see a bid answerable by the person who owns it.
--
-- `shared_by` is pinned to the caller so a share cannot be attributed to
-- somebody else, which would make the audit trail a fiction.
create policy rfp_shares_insert on public.rfp_shares
  for insert to authenticated
  with check (
    shared_by = (select auth.uid())
    and ((select public.is_admin()) or public.owns_rfp(rfp_id))
  );

create policy rfp_shares_delete on public.rfp_shares
  for delete to authenticated
  using ((select public.is_admin()) or public.owns_rfp(rfp_id));

-- --------------------------------------------------------------- the grant ---

-- The one policy this whole migration exists to widen. Same shape as 0019 left
-- it, with shared tenders added as a third way in; the admin check stays first
-- so the common case still short-circuits before reaching the subquery.
--
-- WHY `in (select unnest(...))` AND NOT `= any ((select ...))`.
-- The second is what this said first, and it does not parse. `ANY` has two
-- forms — one taking an array expression, one taking a subquery — and a bare
-- SELECT inside its parentheses is read as the subquery form, which expects a
-- set of uuid rows. `shared_rfp_ids()` returns a single uuid[], so Postgres
-- compares uuid to uuid[] and refuses: 42883, operator does not exist.
--
-- The `(select ...)` wrapper was there to force single evaluation, per 0019.
-- Unnesting into an uncorrelated subquery keeps that property by a different
-- route: nothing in it depends on the row, so the planner runs it once and
-- hashes the result rather than calling the function per row.
drop policy if exists rfps_select on public.rfps;
create policy rfps_select on public.rfps
  for select to authenticated
  using (
    (select public.is_admin())
    or user_id = (select auth.uid())
    or id in (select unnest(public.shared_rfp_ids()))
  );

comment on table public.teams is
  'Standing groups of members, used as the subject of a share. Managed by the super user.';
comment on table public.rfp_shares is
  'Read access to one tender, granted to one member or one team by its owner or by oversight. Never grants write.';



-- ---------------------------------------------------------------------------
-- 0040_proposal_design.sql
-- ---------------------------------------------------------------------------

-- A proposal drafted into the firm's designed template, stored as its words.
--
-- WHAT CHANGED ABOVE THIS. Drafting used to produce Markdown, which the console
-- exported to Word. It now fills the designed HTML template in
-- proposal-templates/ — same stylesheet, same layout, same institutional
-- images, this tender's content. See src/documents/template-draft.ts.
--
-- WHY THIS IS NOT A COLUMN HOLDING THE HTML.
-- The house template is 3.6MB, nearly all of it base64 images that are identical
-- in every proposal ever written from it. Storing the filled document would put
-- that 3.6MB in a row per draft, and a tender with five attempts behind it would
-- carry eighteen megabytes of the same logo. It also fixes the design at the
-- moment of drafting: correct a colour in the template and every proposal
-- already written keeps the old one, invisibly, because what was saved was a
-- snapshot rather than a document.
--
-- So a draft stores the *answers* — roughly 350 short strings, about fifty
-- kilobytes — and the document is rebuilt from the current template whenever it
-- is opened. `content` keeps the readable text of the same proposal, which is
-- what the "show text" panel reads, what a starred model answer teaches the
-- drafter, and what survives if the template it was written into is ever
-- deleted.
--
-- Nullable by default rather than backfilled: every proposal written before this
-- is Markdown, and an empty `design` is exactly what says so.
alter table public.proposals
  add column if not exists design jsonb not null default '{}'::jsonb;

comment on column public.proposals.design is
  'Filled slot values for a proposal drafted into a designed template: {template, values, unfilled, failures}. Empty for Markdown drafts and for uploads.';
